MPZ_st.name='MPZ'; 
MPZ_st.lat=51.5303;
MPZ_st.lon=12.9339;
MPZ_st.alt=86;
MPZ_st.env='con';
MPZ_st.footp='U';
%%

MPZ_rd=read_betsy('MPZ_2007_2017',MPZ_st.name);
%%
datevec(MPZ_rd.Time(1)) %[output:24548277]
datevec(MPZ_rd.Time(end)) %[output:192a9a6e]
prctile(MPZ_rd.U_S,[5 50 95]) %[output:4235fdeb]
plotFigControl(MPZ_rd,MPZ_st.name); %[output:7329c48f] %[output:85b8a344] %[output:9390a332] %[output:32cbf028] %[output:6fae5ae8] %[output:8683ff35] %[output:13aaaf69] %[output:01e1b7ef]

figure; %[output:6271f732]
plot(MPZ_rd.Time,MPZ_rd.U_S); %[output:6271f732]
% 1 size cut, ok
% sc: ok, max in winter, no negatives
% abs: 2 size cut, max in winter, no negatives

%%
lambdaSC=[450;550;700]*ones(1,4);
lambdaAE=[467;530;660]*ones(1,4);
lambdaAE7=[370 470 520 590 660 880 950];
MPZ_cal=compute_exp_SSA(MPZ_rd,lambdaSC, lambdaAE);
plotFigControl_cal(MPZ_cal, MPZ_st.name); %[output:20db6d20] %[output:8b106e66] %[output:8802f92d]
%%
%Questions:
%problems:
%SCA: When was the nephelometer change from 3561 to 3563 ?
% sca+ abs: are the higher values at the end of January 2017- begin of February 2017 real ? they have to be invalidated ?
%sca: the ratio BsG/BsR and BsB/BsR made a jump in March 2008. Is there any changes ?
%sca: the BbsF fraction is much lower in 2008. Do you know why ?
%backsca: the BbsB/BbsG ratio is strange in November 2015: is it real ?

%abs: are the low values of December 2011-January 2012 real ?
%%
period1=timerange('2008-01-01','2008-12-31');
period2=timerange('2009-01-01','2009-12-31');
TT1=MPZ_cal(period1,:);
TT2=MPZ_cal(period2,:);
nanmean(TT1.BbsFG) %[output:378cd25e]
nanmean(TT2.BbsFG) %[output:7497e8c1]

%%

MPZ_tr=MPZ_rd;
%MPZ_tr=outerjoin(MPZ_rd, MPZ_cal);
MPZ_tr.y=year(MPZ_tr.Time);
% begin at the beginning of a year: 2007
% end 2017

%not necessary to analysee dry
MPZ_tr.U_S=[];
names=fieldnames(MPZ_tr);
c=endsWith(names,["dry";"3"]) | startsWith(names,["T1";"T0";"T_";"P_";"P1_";"P0_"]);
N=names(c);
for i=1:length(N)
    MPZ_tr.(N{i})=[];
end
%scatG: 2007-2017
%MPZ_tr.BsB_S=[];
MPZ_tr.BsR_S=[];
%Bsc: 2008-2017
MPZ_tr.BbsB_S=[];
MPZ_tr.BbsR_S=[];
%abs: 12.12.2011-5.1.2012 zu invalidieren
P=timerange('2011-12-12','2013-01-05');
MPZ_tr.BaR_A(P)=NaN;
%sonst 2007-2017 zu brauchen

%corrected abs to green for SSA trend
MPZ_tr.BaR_A=MPZ_tr.BaR_A.*(637/550);
%recalculate values
MPZ_cal2=compute_exp_SSA(MPZ_tr,lambdaSC, lambdaAE);
%BbsFG 2008 zu invalidieren: zu klein, weisst man nicht warum
P=timerange('2008-01-01','2008-12-31');
MPZ_cal2.BbsFG(P)=NaN;
MPZ_tr=outerjoin(MPZ_tr, MPZ_cal2);
 
%SSA: 2007-2017
%%
MPZ_result= all_trend_STN(MPZ_tr,MPZ_st);  %[output:5146265b] %[output:6ee3ea04] %[output:1893f026] %[output:48b8cccb] %[output:5d410b74] %[output:5a712862] %[output:6febd6cc] %[output:081793f2] %[output:5a4393c5] %[output:525a9f4d] %[output:070227d6] %[output:3d36de73] %[output:11be8298] %[output:279021f5] %[output:4e583ebd] %[output:721120bf] %[output:76f5a4af] %[output:196128e0] %[output:1360a84e] %[output:869fdf1b] %[output:89967647] %[output:42f66c34] %[output:10a11b95] %[output:976dd99a] %[output:94210016] %[output:8a31e723] %[output:2ccfa444] %[output:2d6d2ddb] %[output:898a6fd6] %[output:934898e3] %[output:50ecf2b6] %[output:13632bc7] %[output:249f05ea] %[output:7df8fcaf] %[output:997f476b] %[output:53227922] %[output:8f077cb8] %[output:1ad40edd] %[output:5c73a152] %[output:3dc044c2] %[output:95ac25e9] %[output:28a9e4e1] %[output:56c816ef] %[output:07536dcb] %[output:8994fd60] %[output:909e642b] %[output:96b5963a] %[output:53af3ede] %[output:5247c50f] %[output:9af32b48] %[output:00a0f079] %[output:40f25438] %[output:3931eb4e] %[output:9acc28a9] %[output:8f977f9a] %[output:2d4674d9] %[output:552f4448] %[output:73fc1f2d]
